"""Shared launcher for folders generated by the experiment catalogue."""
from __future__ import annotations

import argparse
import json
import subprocess
import sys
from pathlib import Path


def main(experiment_dir: Path) -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--execute", type=int, metavar="N", help="execute recovered command N (1-based)")
    parser.add_argument("--command", nargs=argparse.REMAINDER, help="explicit replacement command")
    args = parser.parse_args()
    manifest = json.loads((experiment_dir / "experiment.json").read_text(encoding="utf-8"))
    root = experiment_dir.parents[2]
    print(json.dumps({
        "catalog_id": manifest["catalog_id"],
        "original_path": manifest["original_path"],
        "source_commit": manifest["source_commit"],
        "reproducibility": manifest["reproducibility"],
        "source_files": manifest["source_files"],
        "commands": {str(i + 1): command for i, command in enumerate(manifest["commands"])},
    }, ensure_ascii=False, indent=2))
    if args.command:
        subprocess.run(args.command, cwd=root, check=True)
        return
    if args.execute is None:
        return
    commands = manifest["commands"]
    if not 1 <= args.execute <= len(commands):
        raise SystemExit(f"command index must be in 1..{len(commands)}")
    subprocess.run(commands[args.execute - 1], cwd=root, shell=True, check=True)


if __name__ == "__main__":
    raise SystemExit("Use the run.py inside a concrete experiment folder")
